mapper.select:
select *
from t_questionnaire_data
where is_deleted = 0
  and groups_id = #{groupsId}
  and questionnaire_id = #{questionnaireId}

select *
from t_questionnaire_data tq
where tq.is_deleted = 0 and tq.groups_id = #{groupsId}
  and tq.questionnaire_id = #{questionnaireId}

SELECT answerSort,
       scaleContext,
       scaleGrade
FROM t_questionnaire_data tq,
     JSON_TABLE(qa_data, '$[*]' COLUMNS ( answerSort VARCHAR ( 255 ) PATH '$.answerSort', scaleContext VARCHAR ( 255 ) PATH '$.scale.scaleContext' ,scaleGrade LONG PATH '$.scale.scaleGrade' )) AS jt
WHERE groups_id = #{groupId}
  AND is_deleted = 0
  AND questionnaire_id = #{questionnaireId}

  AND answerSort = #{answerSort}
  AND scaleContext IS NOT NULL

ORDER BY answerSort,
         scaleContext;
